exports.makeCache = (load, now) => {
  const entries = new Map();
  return key => {
    if (typeof key !== "string") throw new TypeError("Cache key must be a string");
    const time = now();
    const entry = entries.get(key);
    if (entry && time - entry.time < 60000) return entry.value;
    const value = load(key);
    entries.set(key, {value, time});
    return value;
  };
};

