exports.watch = (source, fn) => {
  source.on("data", fn);
  try {
    source.on("end", fn);
  } catch (error) {
    try {
      source.off("data", fn);
    } catch {
      // Keep the listener registration error as the one returned to the caller.
    }
    throw error;
  }
  return () => { source.off("data", fn); source.off("end", fn); };
};

