const assert = require("node:assert/strict");
const {register} = require("./spec.cjs");

function collect(start) {
  const hooks = {};
  let run;
  register({
    beforeAll(fn) { hooks.beforeAll = fn; },
    afterAll(fn) { hooks.afterAll = fn; },
    test(fn) { run = fn; },
    start
  });
  return {hooks, run};
}

let starts = 0;
const filtered = collect(() => { starts++; });
assert.equal(starts, 0);
assert.equal(typeof filtered.hooks.beforeAll, "function");
assert.equal(typeof filtered.run, "function");

const calls = [];
const requestError = new Error("request failed");
const selected = collect(() => {
  starts++;
  return {
    ready() { calls.push("ready"); },
    request() { calls.push("request"); throw requestError; },
    close() { calls.push("close"); }
  };
});
selected.hooks.beforeAll();
assert.throws(() => {
  try { selected.run(); } finally { selected.hooks.afterAll(); }
}, error => error === requestError);
assert.deepEqual(calls, ["ready", "request", "close"]);

const setupError = new Error("setup failed");
const setupCalls = [];
const setupFailure = collect(() => ({
  ready() { setupCalls.push("ready"); throw setupError; },
  request() { setupCalls.push("request"); },
  close() { setupCalls.push("close"); }
}));
assert.throws(() => setupFailure.hooks.beforeAll(), error => error === setupError);
setupFailure.hooks.afterAll();
assert.deepEqual(setupCalls, ["ready", "close"]);

