const {register} = require("./spec.cjs");
for (const failAt of [null, "start", "ready", "request"]) {
  const calls = [];
  const failure = new Error(failAt);
  let before, after, runTest;
  register({
    beforeAll(fn) { before = fn; },
    afterAll(fn) { after = fn; },
    test(fn) { runTest = fn; },
    start() {
      calls.push("start");
      if (failAt === "start") throw failure;
      return {
        ready() { calls.push("ready"); if (failAt === "ready") throw failure; },
        request() { calls.push("request"); if (failAt === "request") throw failure; return "response"; },
        close() { calls.push("close"); }
      };
    }
  });
  assert.deepEqual(calls, []);
  let caught;
  try {
    before();
    assert.equal(runTest(), "response");
  } catch (error) {
    caught = error;
  } finally {
    after();
  }
  if (failAt) assert.equal(caught, failure);
  else assert.equal(caught, undefined);
  const expected = failAt === "start" ? ["start"] : failAt === "ready" ? ["start", "ready", "close"] : ["start", "ready", "request", "close"];
  assert.deepEqual(calls, expected);
}

